using System.Collections.Generic;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
using MaxWorlds.Arena;
using MaxWorlds.Core;

namespace MaxWorlds.Tests.EditMode
{
    /// <summary>
    /// MV-1233 (one new EditMode test, MV-465 Rule 1) — the Mothership's full 30-area layout,
    /// generated by <c>Tools/World5/generate_mothership_layout.py</c> from the Areas tab of
    /// <c>MVW_World5_Design.xlsx</c> (47 cradles, 903 robots). Area 1 (MV-1232's own build) is
    /// carried unchanged; areas 2-30 are this ticket's own.
    ///
    /// Fails on base commit 7656406 (MV-1232's own placeholder "a1_out_stub" beyond area 1, no
    /// areas 2-30 at all): <c>cfg.areas</c> only ever resolves 2 combat-area ids ("a1" and
    /// nothing past it), the cradle sum reads 1 not 47, and every per-area garrison count below
    /// reads 0 for every area but a1.
    ///
    /// Tier 2 (resolved values), testing policy v2: per-area garrison/cradle COUNTS are the
    /// authored content itself (same "the list length IS the content" idiom
    /// <c>MV1232HangarBayTests</c> already uses for a1's own garrison), but reachability is
    /// proven on the BUILT colliders (<see cref="MapRuntime.Build"/> + the real
    /// <see cref="ShipDressing.Dress"/> pass) via a grid flood fill at Max's own
    /// CharacterController radius/height — the same idiom <c>MV900World2WalkabilityTests</c> and
    /// <c>MV1232HangarBayTests</c> both already established, generalised here across all 30
    /// areas rather than one.
    /// </summary>
    public sealed class MV1233MothershipLayoutTests
    {
        private const float Cell = 0.25f;

        // Max (Greybox)'s own CharacterController, Backyard_Slice.unity.
        private const float Radius = 0.5f;
        private const float Height = 2f;

        private const int OpeningSearchRadiusCells = 6; // 1.5 m either side of an authored mouth/point

        // Areas tab (MVW_World5_Design.xlsx) column G, areas 1-30 in order — the per-area robot
        // count every area's built garrison must match exactly. MV-1238 hand-added 2 Tractor
        // garrison entries each to a15 (index 14), a16 (15), a22 (21), a23 (22) and a30 (29) — the
        // only five counts that differed from the Areas tab's own pre-Tractor column G. MV-1244
        // hand-added 2 Welder garrison entries each to a8 (index 7), a12 (11), a22 (21) and a24 (23) —
        // a22 already carries a Tractor pair, so its own +2 stacks onto that ticket's own total.
        private static readonly int[] ExpectedRobotCounts =
        {
            14, 18, 16, 22, 24, 26, 22, 36, 28, 26,
            24, 32, 30, 26, 39, 30, 32, 34, 32, 28,
            36, 44, 38, 40, 32, 40, 40, 40, 40, 32,
        };

        private const int ExpectedAreaCount = 30;
        private const int ExpectedCradleTotal = 47;

        [Test]
        public void AllThirtyAreas_SumCradles47_RobotCountsMatchAreasTab_AndFloodFillGateToGateAndToEveryCradle()
        {
            WorldConfig cfg = WorldLibrary.Load(WorldLibrary.Mothership);
            Assert.IsNotNull(cfg, "the Mothership's own shipped config must load for this test to mean anything");

            var combatAreas = new List<WorldArea>();
            for (int i = 1; i <= ExpectedAreaCount; i++)
            {
                WorldArea a = cfg.Area($"a{i}");
                Assert.IsNotNull(a, $"area 'a{i}' must exist");
                combatAreas.Add(a);
            }

            int cradleTotal = combatAreas.Sum(a => a.cradles?.Length ?? 0);
            Assert.AreEqual(ExpectedCradleTotal, cradleTotal, "the 30 areas must author 47 cradles between them");

            for (int i = 0; i < ExpectedAreaCount; i++)
            {
                WorldArea a = combatAreas[i];
                int actual = a.garrison?.Length ?? 0;
                Assert.AreEqual(ExpectedRobotCounts[i], actual,
                    $"area '{a.id}' must garrison {ExpectedRobotCounts[i]} robots, per the Areas tab");
            }

            Assert.IsTrue(WorldMapLoader.TryLoad(cfg, out MapData map, out string loadReason), loadReason);

            var root = new GameObject("MV-1233 Mothership Root");
            try
            {
                MapBuild built = MapRuntime.Build(map, root.transform);
                ShipDressing.Dress(root.transform, cfg, built.Cover);
                Physics.SyncTransforms(); // autoSyncTransforms is off project-wide (DynamicsManager.asset)

                var cradlePadByArea = new Dictionary<string, List<Vector2>>();
                foreach (WorldArea a in combatAreas)
                {
                    var pads = new List<Vector2>();
                    foreach (WorldCradle crCfg in a.cradles ?? System.Array.Empty<WorldCradle>())
                    {
                        Factories.AssemblyCradle built1 = built.Cradles.FirstOrDefault(c =>
                            Vector3.Distance(c.transform.position, new Vector3(crCfg.x, c.transform.position.y, crCfg.z)) < 0.5f);
                        Assert.IsNotNull(built1, $"cradle '{crCfg.id}' in '{a.id}' was never built");

                        Vector3 outDir = built1.transform.forward;
                        const float cradleHalf = WorldMapLoader.CradleSize * 0.5f;
                        const float outPadHalf = 1f; // AssemblyCradle's own 2x2 m out pad
                        Vector3 padCenter = built1.transform.position + outDir * (cradleHalf + outPadHalf);
                        pads.Add(new Vector2(padCenter.x, padCenter.z));
                    }
                    cradlePadByArea[a.id] = pads;
                }

                var failures = new List<string>();

                for (int i = 0; i < ExpectedAreaCount; i++)
                {
                    WorldArea a = combatAreas[i];
                    string inGateId = $"g{i}";               // g0 (stub->a1), g1 (a1->a2), ... g29 (a29->a30)
                    string outGateId = i < ExpectedAreaCount - 1 ? $"g{i + 1}" : null;

                    MapLink inLink = map.links.FirstOrDefault(l => l != null && l.gate == inGateId);
                    Assert.IsNotNull(inLink, $"gate '{inGateId}' (area '{a.id}'s IN gate) must exist");
                    Vector2 inMouth = GateMouth(map, inLink);

                    HashSet<(int, int)> open = Rasterize(a.Footprint);
                    (int, int)? inCell = FindNearestOpen(inMouth, open);
                    if (inCell == null)
                    {
                        failures.Add($"area '{a.id}': IN gate '{inGateId}' has no walkable cell within 1.5 m of it");
                        continue;
                    }

                    var visited = new HashSet<(int, int)> { inCell.Value };
                    var queue = new Queue<(int, int)>();
                    queue.Enqueue(inCell.Value);
                    while (queue.Count > 0)
                    {
                        (int gx, int gz) c = queue.Dequeue();
                        TryVisit((c.gx + 1, c.gz), open, visited, queue);
                        TryVisit((c.gx - 1, c.gz), open, visited, queue);
                        TryVisit((c.gx, c.gz + 1), open, visited, queue);
                        TryVisit((c.gx, c.gz - 1), open, visited, queue);
                    }

                    if (outGateId != null)
                    {
                        MapLink outLink = map.links.FirstOrDefault(l => l != null && l.gate == outGateId);
                        Assert.IsNotNull(outLink, $"gate '{outGateId}' (area '{a.id}'s OUT gate) must exist");
                        Vector2 outMouth = GateMouth(map, outLink);
                        AssertReached(outMouth, open, visited, $"area '{a.id}': its OUT gate '{outGateId}'", failures);
                    }

                    foreach (Vector2 pad in cradlePadByArea[a.id])
                        AssertReached(pad, open, visited, $"area '{a.id}': a cradle's out pad", failures);
                }

                Assert.IsTrue(failures.Count == 0, "MV-1233 flood-fill failures:\n" + string.Join("\n", failures));
            }
            finally
            {
                Object.DestroyImmediate(root);
            }
        }

        private static void AssertReached(Vector2 point, HashSet<(int, int)> open, HashSet<(int, int)> visited,
            string label, List<string> failures)
        {
            (int, int)? cell = FindNearestOpen(point, open);
            if (cell == null)
            {
                failures.Add($"{label} has no walkable cell within 1.5 m of it");
                return;
            }
            if (!visited.Contains(cell.Value))
                failures.Add($"{label} is not reached from the IN gate by flood fill");
        }

        private static Vector2 GateMouth(MapData map, MapLink link)
        {
            Assert.IsTrue(MapGeometry.Doorway(map, link, out bool alongX, out float coord, out Span hole),
                $"gate '{link.gate}' has no resolvable doorway");
            return alongX ? new Vector2(hole.Mid, coord) : new Vector2(coord, hole.Mid);
        }

        private static HashSet<(int, int)> Rasterize(Rect rect)
        {
            var open = new HashSet<(int, int)>();
            int gxMin = Mathf.FloorToInt(rect.xMin / Cell);
            int gxMax = Mathf.CeilToInt(rect.xMax / Cell) - 1;
            int gzMin = Mathf.FloorToInt(rect.yMin / Cell);
            int gzMax = Mathf.CeilToInt(rect.yMax / Cell) - 1;

            for (int gx = gxMin; gx <= gxMax; gx++)
            {
                float cx = (gx + 0.5f) * Cell;
                for (int gz = gzMin; gz <= gzMax; gz++)
                {
                    float cz = (gz + 0.5f) * Cell;
                    if (!IsBlocked(cx, cz)) open.Add((gx, gz));
                }
            }
            return open;
        }

        private static void TryVisit((int gx, int gz) k, HashSet<(int, int)> open, HashSet<(int, int)> visited,
            Queue<(int, int)> queue)
        {
            if (visited.Contains(k) || !open.Contains(k)) return;
            visited.Add(k);
            queue.Enqueue(k);
        }

        private static (int, int)? FindNearestOpen(Vector2 point, HashSet<(int, int)> open)
        {
            int cgx = Mathf.FloorToInt(point.x / Cell);
            int cgz = Mathf.FloorToInt(point.y / Cell);
            var center = (cgx, cgz);
            if (open.Contains(center)) return center;

            for (int ring = 1; ring <= OpeningSearchRadiusCells; ring++)
            {
                for (int dx = -ring; dx <= ring; dx++)
                {
                    for (int dz = -ring; dz <= ring; dz++)
                    {
                        if (Mathf.Max(Mathf.Abs(dx), Mathf.Abs(dz)) != ring) continue;
                        var k = (cgx + dx, cgz + dz);
                        if (open.Contains(k)) return k;
                    }
                }
            }
            return null;
        }

        private static readonly Collider[] s_overlapBuffer = new Collider[32];

        private static bool IsBlocked(float x, float z)
        {
            var p0 = new Vector3(x, Radius, z);
            var p1 = new Vector3(x, Height - Radius, z);
            int count = Physics.OverlapCapsuleNonAlloc(p0, p1, Radius, s_overlapBuffer, ~0, QueryTriggerInteraction.Ignore);
            for (int i = 0; i < count; i++)
                if (s_overlapBuffer[i].GetComponent<StructuralFloor>() == null) return true;
            return false;
        }
    }
}
